import{_ as t,o,c as r,a4 as a}from"./chunks/framework.DpieW3qv.js";const m=JSON.parse('{"title":"activeSource: local vs smartsheet","description":"","frontmatter":{},"headers":[],"relativePath":"excel/activeSource-comparison.md","filePath":"excel/activeSource-comparison.md","lastUpdated":null}'),d={name:"excel/activeSource-comparison.md"};function s(c,e,n,l,i,h){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="activesource-local-vs-smartsheet" tabindex="-1">activeSource: local vs smartsheet <a class="header-anchor" href="#activesource-local-vs-smartsheet" aria-label="Permalink to &quot;activeSource: local vs smartsheet&quot;">​</a></h1><p>Comparison of <code>dev-env/.ocapi-config.json</code> → <code>workspace.activeSource</code> for <code>make pull</code> and <code>make pull CONVERT=1</code>.</p><p><strong>Smartsheet flow:</strong> Fetch raw Excel → compare headers to CONVERTED required keys → if match, parse directly; else run convert-excel, overwrite <code>data/excel/LOFT (Converted).xlsx</code>, then parse. <code>CONVERT=1</code> forces convert (skips header check).</p><hr><h2 id="activesource-local" tabindex="-1">activeSource: <strong>local</strong> <a class="header-anchor" href="#activesource-local" aria-label="Permalink to &quot;activeSource: **local**&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What happens</th></tr></thead><tbody><tr><td><code>make pull</code></td><td>Reads <strong><code>data/excel/LOFT (Converted).xlsx</code></strong> (or Ann equivalent) from disk. No network. Parses and writes refresh JSONs to <code>dev-env/loft/refreshes/</code>.</td></tr><tr><td><code>make pull CONVERT=1</code></td><td><strong>Same as above.</strong> <code>CONVERT=1</code> is only used when <code>activeSource</code> is <code>smartsheet</code>; with <code>local</code> it is ignored.</td></tr></tbody></table><ul><li><strong>Use when:</strong> You work from the local “converted” Excel file (e.g. after downloading from Smartsheet once, or editing it by hand).</li><li><strong>Requires:</strong> Nothing beyond the file at <code>workspace.sources.local.path</code> (default <code>data/excel/LOFT (Converted).xlsx</code>).</li></ul><hr><h2 id="activesource-smartsheet" tabindex="-1">activeSource: <strong>smartsheet</strong> <a class="header-anchor" href="#activesource-smartsheet" aria-label="Permalink to &quot;activeSource: **smartsheet**&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What happens</th></tr></thead><tbody><tr><td><code>make pull</code></td><td>Fetches from Smartsheet → <strong>header check</strong>: if sheet has REFRESH_NAME, REFRESH_DATE, ACTION, ASSET_TYPE, SITE_LOCATION → parse directly. Else → convert to <code>data/excel/LOFT (Converted).xlsx</code> → parse.</td></tr><tr><td><code>make pull CONVERT=1</code></td><td>Fetches from Smartsheet → <strong>always convert</strong> (skip header check) → overwrites <code>data/excel/LOFT (Converted).xlsx</code> → parse. Use when you want to save the converted file even if headers match.</td></tr></tbody></table><ul><li><strong>Use when:</strong> You want the app to use live data from Smartsheet (either parse-only from temp file, or download and overwrite the converted file).</li><li><strong>Requires:</strong><ul><li><code>SMARTSHEET_API_KEY</code> in environment (or in <code>.env</code>; CLI loads it via <code>dotenv</code>).</li><li>Sheet ID: env var <code>SMARTSHEET_SHEET_ID_LOFT</code> / <code>SMARTSHEET_SHEET_ID_ANN</code> (brand is passed from CLI so the correct env var is used).</li></ul></li><li><strong>Caching:</strong> Downloads are cached for 15 minutes by default (configurable via <code>cacheTtlMinutes</code>). Use <code>NO_CACHE=1</code> to force refresh.</li></ul><hr><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th><strong>local</strong></th><th><strong>smartsheet</strong></th></tr></thead><tbody><tr><td><strong>Source of data</strong></td><td><code>data/excel/LOFT (Converted).xlsx</code> (or Ann)</td><td>Smartsheet API (Excel export)</td></tr><tr><td><strong>Network</strong></td><td>No</td><td>Yes</td></tr><tr><td><strong>CONVERT=1</strong></td><td>Ignored</td><td>Force convert even when headers match</td></tr><tr><td><strong>Typical use</strong></td><td>Offline / fixed snapshot</td><td>Live Smartsheet data</td></tr></tbody></table><p>After either source, the auto-build (triggered by <code>make pull</code> and optionally rerun via <code>make refresh</code>) uses the same parsed refresh data under <code>dev-env/</code>.</p><hr><h2 id="why-the-app-can-parse-smartsheet-already-no-convert-required" tabindex="-1">Why the app can parse Smartsheet already (no convert required) <a class="header-anchor" href="#why-the-app-can-parse-smartsheet-already-no-convert-required" aria-label="Permalink to &quot;Why the app can parse Smartsheet already (no convert required)&quot;">​</a></h2><p>The app parses the <strong>raw</strong> Smartsheet Excel export (e.g. the temp file from <code>make pull</code> with <code>activeSource: smartsheet</code>) without running <code>convert-excel</code>. That works because:</p><ol><li><p><strong>Same file format</strong> — The Smartsheet source requests <code>Accept: application/vnd.ms-excel</code>, so the API returns a real <code>.xlsx</code>. The same Excel parser and pipeline are used for local files and Smartsheet downloads.</p></li><li><p><strong>Excel config (header aliases)</strong> — <code>src/config/excel.config.js</code> defines <strong>HEADER_ALIASES</strong>: each canonical field (e.g. <code>REFRESH_NAME</code>, <code>REFRESH_DATE</code>, <code>DEVICE</code>, <code>ASSET_TYPE</code>) is mapped to a list of accepted column names. Smartsheet-style names are included, e.g.:</p><ul><li><code>DEVICE</code> ← <code>&quot;BANNER LABEL&quot;</code>, <code>&quot;DATE/TIME&quot;</code>, <code>&quot;CHANGEOUT LABEL&quot;</code></li><li><code>REFRESH_NAME</code> ← <code>&quot;REFRESH NAME&quot;</code>, <code>&quot;PROJECT SUMMARY&quot;</code>, <code>&quot;INITIATIVE NAME&quot;</code></li><li><code>REFRESH_DATE</code> ← <code>&quot;CHANGEOUT DATE&quot;</code>, <code>&quot;LIVE DATE&quot;</code>, <code>&quot;GO LIVE&quot;</code> So whatever column headers Smartsheet exports, the parser can resolve them to the canonical fields.</li></ul></li><li><p><strong>Parser behavior</strong> — <code>ExcelParser</code> scans the first 40 rows to find the header row (the row with the most matches to the alias lookup), then builds a column map and detects sheet kind (CONVERTED, BANNER, or FLAT_TIMED). Banner/generic parsing already allows blank <code>WEB_PROD_CODED</code>, label from <code>DEVICE</code> or <code>REFRESH_NAME</code>, and <code>ASSET_TYPE</code> variants (e.g. CAROUSEL). So the structure and content of the Smartsheet export fit the same model.</p></li></ol><p><strong>CONVERT=1</strong> is therefore optional: it downloads from Smartsheet and overwrites <code>data/excel/LOFT (Converted).xlsx</code> with a <strong>normalized</strong> 20-column layout (same columns every time, reordered). Parsing works either from that normalized file or directly from the raw download.</p><hr><h2 id="test-results-both-sources" tabindex="-1">Test results (both sources) <a class="header-anchor" href="#test-results-both-sources" aria-label="Permalink to &quot;Test results (both sources)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>activeSource</th><th>Command</th><th>Result</th></tr></thead><tbody><tr><td><strong>local</strong></td><td><code>make pull</code></td><td>✅ Reads <code>LOFT (Converted).xlsx</code>, 45 refreshes, 2684 items, no network.</td></tr><tr><td><strong>local</strong></td><td><code>make pull CONVERT=1</code></td><td>✅ Same as above (CONVERT ignored).</td></tr><tr><td><strong>smartsheet</strong></td><td><code>make pull</code></td><td>✅ Fetches from API (e.g. 160.6 KB), parses temp file, 45 refreshes. Does not touch converted file.</td></tr><tr><td><strong>smartsheet</strong></td><td><code>make pull CONVERT=1</code></td><td>✅ Fetches → converts → overwrites <code>data/excel/LOFT (Converted).xlsx</code> → parses that file.</td></tr></tbody></table>',23)])])}const p=t(d,[["render",s]]);export{m as __pageData,p as default};
